transforms=[]
for k in range(4):
 s=obj
 for _ in range(k): s={(c,-r) for r,c in s}
 for refl in (False,True):
  ss={(r,-c) for r,c in s} if refl else s
  minr=min(r for r,c in ss); minc=min(c for r,c in ss)
  norm=frozenset((r-minr,c-minc) for r,c in ss)
  if norm not in [x[0] for x in transforms]: transforms.append((norm,(k,refl)))
